    public static bool TryGetValue(string languageCode, string key, out string value)
    {
        if (Translations.TryGetValue(languageCode, out var translations) &&
            translations.TryGetValue(key, out value!))
            return true;

        value = string.Empty;
        return false;
    }

    private static IReadOnlyDictionary<string, string> Create(
        string interfaceWord,
        string grid,
        string list,
        string selectApp,
        string rightClickHint,
        string noEntries,
        string hideContents,
        string showContents,
        string contentsHidden,
        string selectContents,
        string batchSelect,
        string batchSelectActive,
        string launchSelected,
        string cancelSelection,
        string selectedCount,
        string overview,
        string swipeHint,
        string launchHint)
    {
        return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["SettingsInterface"] = interfaceWord,
            ["InterfaceGrid"] = grid,
            ["InterfaceGridDescription"] = grid,
            ["InterfaceList"] = list,
            ["InterfaceListDescription"] = list,
            ["InterfaceListHeader"] = selectApp,
            ["InterfaceListSelectHint"] = rightClickHint,
            ["InterfaceListEmpty"] = noEntries,
            ["InterfaceListNoEntries"] = noEntries,
            ["HideContents"] = hideContents,
            ["ShowContents"] = showContents,
            ["ContentsHidden"] = contentsHidden,
            ["SelectContents"] = selectContents,
            ["ShowHiddenContents"] = showContents,
            ["ContentSelectionTitle"] = selectContents,
            ["ContentSelectionHint"] = selectContents,
            ["NoContentsToSelect"] = noEntries,
            ["BatchSelect"] = batchSelect,
            ["BatchSelectActive"] = batchSelectActive,
            ["LaunchSelected"] = launchSelected,
            ["CancelSelection"] = cancelSelection,
            ["SelectedCount"] = selectedCount,
            // The showcase name and description are left to LocalizationService:
            // the old per-language strings meant "overview" / "list view".
            ["InterfaceToggleHint"] = interfaceWord,
            ["InterfaceSwipeHint"] = swipeHint,
            ["InterfaceLaunchHint"] = launchHint
        };
